package com.commutemate.ride;
import com.commutemate.common.TenantContextHolder; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.time.Instant; import java.time.temporal.ChronoUnit; import java.util.List; import java.util.UUID; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/ride-offers") public class RideOfferController { private final RideOfferRepository offers; private final LocationRepository locations; public RideOfferController(RideOfferRepository offers,LocationRepository locations){this.offers=offers;this.locations=locations;} public record CreateOffer(@NotNull UUID locationId,@NotNull Instant departureAt,@NotBlank String originGeohash,@Min(1) @Max(8) short seatsAvailable,@NotBlank String commuteIntent){} @PostMapping public RideOffer create(@Valid @RequestBody CreateOffer r){var c=TenantContextHolder.getRequired(); var location=locations.findById(r.locationId()).orElseThrow(()->new IllegalArgumentException("location not found")); if(!location.getTenantId().equals(c.tenantId())) throw new SecurityException("location belongs to another tenant"); if(r.departureAt().isBefore(Instant.now().minus(2,ChronoUnit.MINUTES))) throw new IllegalArgumentException("departureAt must be in the future"); return offers.save(new RideOffer(c.tenantId(),c.userId(),r.locationId(),r.departureAt(),r.originGeohash(),r.seatsAvailable(),r.commuteIntent().toUpperCase())); } @GetMapping("/search") public List<RideOffer> search(@RequestParam UUID locationId,@RequestParam Instant from,@RequestParam Instant to){var c=TenantContextHolder.getRequired(); if(to.isBefore(from)) throw new IllegalArgumentException("to must be after from"); return offers.findAllByTenantIdAndLocationIdAndStatusAndDepartureAtBetweenOrderByDepartureAt(c.tenantId(),locationId,"OPEN",from,to);} }
